//! 🌳 CREATE TREE — Rocket's quest-tree atelier.
//!
//! A persistent, multi-instance authoring environment: each Quest Tree is a
//! self-contained hierarchical overlay of quests, challenges, lore-gates and
//! progression nodes, commissioned by the user and generated by Rocket
//! **exclusively from the authoritative grimoires** (the live knowledge base).
//!
//! Integrity rules (spec): trees are pedagogical overlays — never a source of
//! truth for game rules. Every node traces to real grimoire sections; nodes
//! are re-validated against the current grimoire and repairable if a section
//! disappears. Completion feeds the global XP/chronicle systems like any
//! other scholarship.

use crate::knowledge::KnowledgeBase;
use crate::GameType;
use chrono::Local;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

// ---------------------------------------------------------------------------
// Model
// ---------------------------------------------------------------------------

/// The commissioning archetypes. Hybrid flavors are expressed through the
/// free-form subtitle and mixed criteria.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum TreeArchetype {
    LinearMastery,
    BranchingWeb,
    OrdealLadder,
    ComparativeNetwork,
    RestorationCampaign,
    TimedTrials,
    NarrativeChronicle,
    EdgeCaseGauntlet,
}

impl TreeArchetype {
    pub const ALL: [TreeArchetype; 8] = [
        TreeArchetype::LinearMastery,
        TreeArchetype::BranchingWeb,
        TreeArchetype::OrdealLadder,
        TreeArchetype::ComparativeNetwork,
        TreeArchetype::RestorationCampaign,
        TreeArchetype::TimedTrials,
        TreeArchetype::NarrativeChronicle,
        TreeArchetype::EdgeCaseGauntlet,
    ];

    pub fn label(&self) -> &'static str {
        match self {
            TreeArchetype::LinearMastery => "Linear Mastery Path",
            TreeArchetype::BranchingWeb => "Branching Decision Web",
            TreeArchetype::OrdealLadder => "Escalating Ordeal Ladder",
            TreeArchetype::ComparativeNetwork => "Comparative Scholarship Network",
            TreeArchetype::RestorationCampaign => "Restoration & Gap-Filling Campaign",
            TreeArchetype::TimedTrials => "Timed Trial Sequence",
            TreeArchetype::NarrativeChronicle => "Narrative Chronicle with Checkpoints",
            TreeArchetype::EdgeCaseGauntlet => "Edge-Case Gauntlet",
        }
    }

    /// Minimum Order rank index required to commission this archetype.
    pub fn rank_gate(&self) -> usize {
        match self {
            TreeArchetype::LinearMastery => 0,
            TreeArchetype::BranchingWeb | TreeArchetype::NarrativeChronicle => 1,
            TreeArchetype::ComparativeNetwork | TreeArchetype::RestorationCampaign => 2,
            TreeArchetype::OrdealLadder | TreeArchetype::TimedTrials => 3,
            TreeArchetype::EdgeCaseGauntlet => 4,
        }
    }

    pub fn parse(word: &str) -> Option<TreeArchetype> {
        Some(match word.to_lowercase().as_str() {
            "linear" | "mastery" => TreeArchetype::LinearMastery,
            "branching" | "branch" | "web" => TreeArchetype::BranchingWeb,
            "ordeal" | "ladder" => TreeArchetype::OrdealLadder,
            "comparative" | "network" => TreeArchetype::ComparativeNetwork,
            "restoration" | "restore" => TreeArchetype::RestorationCampaign,
            "timed" | "trial" | "trials" => TreeArchetype::TimedTrials,
            "narrative" | "chronicle" => TreeArchetype::NarrativeChronicle,
            "edge" | "gauntlet" | "edge-case" => TreeArchetype::EdgeCaseGauntlet,
            _ => return None,
        })
    }
}

/// Difficulty curve of the XP economy across tiers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Curve {
    Gentle,
    Linear,
    Steep,
}

impl Curve {
    /// XP for a node at `tier` (0-based).
    pub fn xp_at(&self, tier: u32) -> u32 {
        match self {
            Curve::Gentle => 30 + 15 * tier,
            Curve::Linear => 40 + 20 * tier,
            Curve::Steep => 30 + 30 * tier,
        }
    }
}

/// Machine-checkable success criteria for one node. Counters are driven by
/// real scholarship events (grounded answers in the realm with a matching
/// discipline, teaching events, consecutive grounded runs) — nothing
/// self-reported.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NodeCriteria {
    /// Grounded answers required in the tree's realm (0 = not used).
    pub grounded_questions: u32,
    /// Discipline (category label) the answers must touch; None = any.
    pub category: Option<String>,
    /// Teaching events required in the realm.
    pub teach_facts: u32,
    /// Consecutive grounded answers required (ordeal nodes).
    pub ordeal_run: u32,
    /// Comparative: one grounded answer in each listed realm.
    pub comparative_realms: Vec<String>,
}

/// One node of a quest tree — fully specified per the commissioning contract.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TreeNode {
    pub id: String,
    /// Depth level (0 = root).
    pub tier: u32,
    pub title: String,
    pub description: String,
    pub criteria: NodeCriteria,
    /// What happens on failure / partial success (displayed guidance).
    pub failure_guidance: String,
    pub xp_reward: u32,
    /// Minimum Order rank index to attempt this node.
    pub rank_required: usize,
    /// Exact grimoire sections this node exercises (traceability).
    pub grimoire_sections: Vec<String>,
    /// Prerequisite node ids — all blocking ones must be completed first.
    pub parents: Vec<String>,
    /// Optional side-branch: the tree can seal without it.
    pub optional: bool,
    /// Rival paths: sealing one rests the others (skipped, not failed).
    pub mutually_exclusive_with: Vec<String>,
    /// Convergence point (many parents, one heir).
    pub convergence: bool,
    // --- live state ---
    #[serde(default)]
    pub progress: u32,
    #[serde(default)]
    pub teach_progress: u32,
    #[serde(default)]
    pub realm_progress: BTreeMap<String, u32>,
    #[serde(default)]
    pub completed: bool,
    /// Set when re-validation finds its sections missing from the grimoire.
    #[serde(default)]
    pub stale: bool,
}

impl TreeNode {
    pub fn target(&self) -> u32 {
        self.criteria.grounded_questions
            + self.criteria.teach_facts
            + self.criteria.ordeal_run
            + self.criteria.comparative_realms.len() as u32
    }

    pub fn progress_line(&self) -> String {
        if !self.criteria.comparative_realms.is_empty() {
            return self
                .criteria
                .comparative_realms
                .iter()
                .map(|r| format!("{} {}/1", r, self.realm_progress.get(r).copied().unwrap_or(0)))
                .collect::<Vec<_>>()
                .join(" · ");
        }
        if self.criteria.ordeal_run > 0 {
            return format!(
                "run {}/{}",
                self.progress.min(self.criteria.ordeal_run),
                self.criteria.ordeal_run
            );
        }
        let teach = self.criteria.teach_facts;
        let qs = self.criteria.grounded_questions;
        if teach > 0 && qs > 0 {
            format!(
                "answers {}/{} · teachings {}/{}",
                self.progress.min(qs),
                qs,
                self.teach_progress.min(teach),
                teach
            )
        } else if teach > 0 {
            format!("teachings {}/{}", self.teach_progress.min(teach), teach)
        } else {
            format!("answers {}/{}", self.progress.min(qs), qs)
        }
    }
}

/// A revision entry — every refinement directive is inscribed.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RevisionEntry {
    pub date: String,
    pub directive: String,
    pub summary: String,
    pub nodes_changed: u32,
}

/// One Quest Tree instance — a living document, fully addressable while
/// active or minimized.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QuestTree {
    pub id: String,
    pub name: String,
    pub subtitle: Option<String>,
    /// Realm display name — must resolve against the registry.
    pub game: String,
    /// Second realm for Comparative Networks.
    pub game2: Option<String>,
    pub archetype: TreeArchetype,
    /// XP economy curve commissioned by the user.
    pub curve: Curve,
    /// Minimum Order rank index to commission/attempt this tree.
    pub rank_gate: usize,
    pub nodes: Vec<TreeNode>,
    // --- independent state ---
    pub xp_earned: u32,
    pub completed_sealed: bool,
    pub notes: String,
    pub revisions: Vec<RevisionEntry>,
    // --- tab semantics ---
    /// false while minimized (tab chip, no data loss).
    pub active: bool,
    /// Archived trees leave the tab bar entirely (restorable).
    pub archived: bool,
    pub created: String,
}

impl QuestTree {
    pub fn node(&self, id: &str) -> Option<&TreeNode> {
        self.nodes.iter().find(|n| n.id == id)
    }

    pub fn completed_count(&self) -> usize {
        self.nodes.iter().filter(|n| n.completed).count()
    }

    pub fn total_xp(&self) -> u32 {
        self.nodes.iter().map(|n| n.xp_reward).sum()
    }

    /// One-line progress summary (for `trees` listings).
    pub fn summary_line(&self) -> String {
        let done = self.completed_count();
        let state = if self.completed_sealed {
            "🏆 sealed"
        } else if self.archived {
            "🗄️ archived"
        } else if self.active {
            "🟢 open"
        } else {
            "📉 minimized"
        };
        format!(
            "{} — {} · {}/{} nodes · {} pages earned · [{}]",
            self.name,
            self.game,
            done,
            self.nodes.len(),
            self.xp_earned,
            state
        )
    }

    /// Nodes whose blocking prerequisites are complete (the live frontier).
    /// Optional parents never block.
    pub fn frontier(&self) -> Vec<String> {
        self.nodes
            .iter()
            .filter(|n| {
                !n.completed
                    && n.parents.iter().all(|p| {
                        self.nodes
                            .iter()
                            .find(|c| c.id == *p)
                            .map(|c| c.completed || c.optional)
                            .unwrap_or(true)
                    })
            })
            .map(|n| n.id.clone())
            .collect()
    }
}

// ---------------------------------------------------------------------------
// Commission parsing
// ---------------------------------------------------------------------------

/// A structured commission, parsed from one desk message.
#[derive(Debug, Clone)]
pub struct Commission {
    pub game: String,
    pub game2: Option<String>,
    pub archetype: TreeArchetype,
    pub depth: u32,
    pub breadth: u32,
    pub curve: Curve,
    pub name: Option<String>,
    pub flavor: Option<String>,
}

/// Parse a commission from the text after `create tree`. Accepted forms:
///   `create tree for minecraft`
///   `create tree branching for terraria depth 4 breadth 2 steep flavor: The Deep Delve`
///   `create tree comparative for minecraft and terraria depth 3`
pub fn parse_commission(rest: &str) -> Result<Commission, String> {
    let mut text = rest.trim().to_string();
    if text.is_empty() {
        return Err("name a realm to commission — e.g. `create tree for minecraft`".into());
    }
    let lower_full = text.to_lowercase();

    // flavor: <free text to end> (original casing preserved).
    let flavor = lower_full.find("flavor:").map(|pos| text[pos + 7..].trim().to_string());
    if let Some(pos) = lower_full.find("flavor:") {
        text = text[..pos].trim().to_string();
    }
    let lower = text.to_lowercase();

    // named <title>
    let name = lower.find(" named ").map(|pos| text[pos + 7..].trim().to_string());
    if let Some(pos) = lower.find(" named ") {
        text = text[..pos].trim().to_string();
    }
    let lower = text.to_lowercase();

    // Numeric directives: depth N / breadth N.
    let mut depth = 3u32;
    let mut breadth = 2u32;
    if let Some(n) = number_after(&lower, "depth") {
        depth = n.clamp(1, 8);
    }
    if let Some(n) = number_after(&lower, "breadth") {
        breadth = n.clamp(1, 3);
    }

    let curve = if lower.contains("gentle") {
        Curve::Gentle
    } else if lower.contains("steep") {
        Curve::Steep
    } else {
        Curve::Linear
    };

    // Archetype: first recognized keyword token.
    let mut archetype = TreeArchetype::LinearMastery;
    for w in lower.split_whitespace() {
        if let Some(a) = TreeArchetype::parse(w.trim_end_matches(':')) {
            archetype = a;
            break;
        }
    }

    // Game clause: text after " for " (also right at the start), with
    // trailing directives stripped.
    let mut clause = if let Some(rest) = lower.strip_prefix("for ") {
        text[4..].to_string()
    } else if let Some(pos) = lower.find(" for ") {
        text[pos + 5..].to_string()
    } else {
        // No explicit "for": drop a leading archetype word if present.
        let first = lower.split_whitespace().next().unwrap_or("");
        match TreeArchetype::parse(first) {
            Some(_) => text[first.len()..].trim().to_string(),
            None => text.clone(),
        }
    };
    for key in [" depth", " breadth", " gentle", " steep"] {
        // Recompute the lowercase view each pass — the clause shrinks as
        // directives are stripped, so stale positions would slice out of bounds.
        let cur = clause.to_lowercase();
        if let Some(pos) = cur.find(key) {
            if pos <= clause.len() {
                clause = clause[..pos].trim().to_string();
            }
        }
    }
    let clause_lower = clause.to_lowercase();

    // Comparative pair: "<a> and <b>".
    let (game, game2, comparative) = if let Some(pos) = clause_lower.find(" and ") {
        (
            clause[..pos].trim().to_string(),
            Some(clause[pos + 5..].trim().to_string()),
            true,
        )
    } else {
        (clause.trim().to_string(), None, false)
    };

    if game.is_empty() {
        return Err("commission needs a realm — e.g. `create tree for minecraft`".into());
    }
    if (comparative || archetype == TreeArchetype::ComparativeNetwork) && game2.is_none() {
        return Err(
            "a Comparative Network needs two realms — e.g. `create tree comparative for minecraft and terraria`"
                .into(),
        );
    }
    Ok(Commission {
        game,
        game2,
        archetype,
        depth,
        breadth,
        curve,
        name,
        flavor,
    })
}

fn number_after(lower: &str, key: &str) -> Option<u32> {
    let mut words = lower.split_whitespace();
    while let Some(w) = words.next() {
        let bare = w.trim_end_matches(':');
        if bare == key {
            if let Some(next) = words.next() {
                return next.trim_end_matches(':').parse::<u32>().ok();
            }
        } else if let Some(rest) = bare.strip_prefix(key) {
            return rest.parse::<u32>().ok();
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Generation — grounded exclusively in the grimoire
// ---------------------------------------------------------------------------

fn push_node(nodes: &mut Vec<TreeNode>, seq: &mut usize, tier: u32, mut n: TreeNode) -> String {
    *seq += 1;
    n.id = format!("n{:02}", seq);
    n.tier = tier;
    let id = n.id.clone();
    nodes.push(n);
    id
}

fn make_node(
    title: String,
    description: String,
    criteria: NodeCriteria,
    failure_guidance: String,
    xp_reward: u32,
    rank_required: usize,
    grimoire_sections: Vec<String>,
    parents: Vec<String>,
    optional: bool,
    convergence: bool,
) -> TreeNode {
    TreeNode {
        id: String::new(),
        tier: 0,
        title,
        description,
        criteria,
        failure_guidance,
        xp_reward,
        rank_required,
        grimoire_sections,
        parents,
        optional,
        mutually_exclusive_with: vec![],
        convergence,
        progress: 0,
        teach_progress: 0,
        realm_progress: BTreeMap::new(),
        completed: false,
        stale: false,
    }
}

fn trim_cat(cat: &str) -> &str {
    cat.trim_start_matches(|c: char| !c.is_ascii_alphabetic())
}

/// Generate a tree from a commission. Fails when the grimoire is blank or a
/// named realm does not exist — trees are never invented.
pub fn generate_tree(
    kb: &KnowledgeBase,
    spec: &Commission,
    tree_id: String,
    resolved: &GameType,
    resolved2: Option<&GameType>,
) -> Result<QuestTree, String> {
    let entries = kb.entries_for_game(resolved);
    if entries.is_empty() {
        return Err(format!(
            "The {} grimoire is blank — teach it first (Restoration), or commission a charted realm.",
            resolved.get_name()
        ));
    }
    if let Some(g2) = resolved2 {
        if kb.entries_for_game(g2).is_empty() {
            return Err(format!(
                "The {} grimoire is blank — pick a charted second realm.",
                g2.get_name()
            ));
        }
    }

    // Real disciplines of this grimoire, strongest first (traceability).
    let mut cat_counts: BTreeMap<&'static str, usize> = BTreeMap::new();
    for e in &entries {
        *cat_counts.entry(e.category.label()).or_insert(0) += 1;
    }
    let mut cats_desc: Vec<(&'static str, usize)> =
        cat_counts.iter().map(|(c, n)| (*c, *n)).collect();
    cats_desc.sort_by(|a, b| b.1.cmp(&a.1));
    let mut cats_asc: Vec<&'static str> =
        cat_counts.iter().map(|(c, _)| *c).collect::<Vec<_>>();
    cats_asc.sort_by_key(|c| cat_counts[c]);

    let rank_gate = spec.archetype.rank_gate();
    let game_name = resolved.get_name().to_string();
    let game2_name = resolved2.map(|g| g.get_name().to_string());
    let mut nodes: Vec<TreeNode> = Vec::new();
    let mut seq: usize = 0;

    match spec.archetype {
        TreeArchetype::LinearMastery | TreeArchetype::NarrativeChronicle => {
            let mut prev: Option<String> = None;
            for tier in 0..spec.depth {
                let cat = cats_desc[tier as usize % cats_desc.len()].0;
                let is_last = tier == spec.depth - 1;
                let qs = if is_last { 3 } else { 2 };
                let teach = if spec.archetype == TreeArchetype::NarrativeChronicle && tier == 1 {
                    1
                } else {
                    0
                };
                let title = if is_last {
                    format!("Grand Colloquy of {}", trim_cat(cat))
                } else {
                    format!("Chapter {} — the {} of {}", tier + 1, trim_cat(cat), game_name)
                };
                let desc = if teach > 0 {
                    format!(
                        "Hold counsel with the grimoire: {} grounded answer(s) touching {}, and inscribe {} teaching(s).",
                        qs, cat, teach
                    )
                } else {
                    format!("Hold counsel with the grimoire: {} grounded answer(s) touching {}.", qs, cat)
                };
                let id = push_node(
                    &mut nodes,
                    &mut seq,
                    tier,
                    make_node(
                        title,
                        desc,
                        NodeCriteria {
                            grounded_questions: qs,
                            category: Some(cat.to_string()),
                            teach_facts: teach,
                            ordeal_run: 0,
                            comparative_realms: vec![],
                        },
                        "Partial counsel counts: each grounded answer advances the chapter; wrong turns are simply re-asked.".into(),
                        spec.curve.xp_at(tier) + if is_last { 40 } else { 0 },
                        rank_gate,
                        vec![cat.to_string()],
                        prev.clone().into_iter().collect(),
                        false,
                        false,
                    ),
                );
                prev = Some(id);
            }
        }
        TreeArchetype::BranchingWeb => {
            let mut prev_ids: Vec<String> = vec![];
            for tier in 0..spec.depth {
                if tier == 0 {
                    let id = push_node(
                        &mut nodes,
                        &mut seq,
                        0,
                        make_node(
                            format!("The Root Inquiry of {}", game_name),
                            "Open the grimoire: one grounded answer anywhere in the realm.".into(),
                            NodeCriteria {
                                grounded_questions: 1,
                                category: None,
                                teach_facts: 0,
                                ordeal_run: 0,
                                comparative_realms: vec![],
                            },
                            "Ask any grounded question — the web unfolds from your first true answer.".into(),
                            spec.curve.xp_at(0),
                            rank_gate,
                            vec![cats_desc[0].0.to_string()],
                            vec![],
                            false,
                            false,
                        ),
                    );
                    prev_ids = vec![id];
                    continue;
                }
                let is_final = tier == spec.depth - 1;
                if is_final {
                    let id = push_node(
                        &mut nodes,
                        &mut seq,
                        tier,
                        make_node(
                            "The Confluence".into(),
                            "Where every branch meets: grounded answers in the realm's deepest discipline.".into(),
                            NodeCriteria {
                                grounded_questions: 2,
                                category: Some(cats_desc[0].0.to_string()),
                                teach_facts: 0,
                                ordeal_run: 0,
                                comparative_realms: vec![],
                            },
                            "The confluence asks twice; each grounded answer counts toward it.".into(),
                            spec.curve.xp_at(tier) + 40,
                            rank_gate,
                            vec![cats_desc[0].0.to_string()],
                            prev_ids.clone(),
                            false,
                            true,
                        ),
                    );
                    let _ = id;
                } else {
                    let mut tier_ids: Vec<String> = vec![];
                    for b in 0..spec.breadth as usize {
                        let cat = cats_desc[(b + tier as usize) % cats_desc.len()].0;
                        let id = push_node(
                            &mut nodes,
                            &mut seq,
                            tier,
                            make_node(
                                format!("Branch {} — {}", b + 1, trim_cat(cat)),
                                format!("Walk this path: 2 grounded answer(s) touching {}.", cat),
                                NodeCriteria {
                                    grounded_questions: 2,
                                    category: Some(cat.to_string()),
                                    teach_facts: 0,
                                    ordeal_run: 0,
                                    comparative_realms: vec![],
                                },
                                "Paths may rest — branch progress is never lost; branches run in parallel.".into(),
                                spec.curve.xp_at(tier),
                                rank_gate,
                                vec![cat.to_string()],
                                prev_ids.clone(),
                                // With multiple branches, the last is an
                                // optional side-path (the web can seal without
                                // it — its parent slot never blocks).
                                spec.breadth > 1 && b + 1 == spec.breadth as usize,
                                false,
                            ),
                        );
                        tier_ids.push(id);
                    }
                    prev_ids = tier_ids;
                }
            }
        }
        TreeArchetype::OrdealLadder | TreeArchetype::TimedTrials => {
            let mut prev: Option<String> = None;
            for tier in 0..spec.depth {
                let run = 2 + tier;
                let id = push_node(
                    &mut nodes,
                    &mut seq,
                    tier,
                    make_node(
                        format!("Ordeal {} — a run of {}", tier + 1, run),
                        format!("{} consecutive grounded answers in {} without faltering.", run, game_name),
                        NodeCriteria {
                            grounded_questions: 0,
                            category: None,
                            teach_facts: 0,
                            ordeal_run: run,
                            comparative_realms: vec![],
                        },
                        "A faltered run resets the count — the ladder does not fall, only the run begins anew.".into(),
                        spec.curve.xp_at(tier) + 10 * run,
                        rank_gate,
                        vec!["any discipline (consecutive grounded answers)".into()],
                        prev.clone().into_iter().collect(),
                        false,
                        false,
                    ),
                );
                prev = Some(id);
            }
        }
        TreeArchetype::ComparativeNetwork => {
            let g2 = game2_name.clone().expect("comparative pair validated");
            let g2t = resolved2.expect("comparative pair validated");
            let cats2: Vec<&'static str> = {
                let mut m: BTreeMap<&'static str, ()> = BTreeMap::new();
                for e in kb.entries_for_game(g2t) {
                    m.entry(e.category.label()).or_insert(());
                }
                m.into_keys().collect()
            };
            let mut prev: Option<String> = None;
            for tier in 0..spec.depth {
                let cat = cats_desc[tier as usize % cats_desc.len()].0;
                let cat2 = cats2.get(tier as usize % cats2.len()).copied().unwrap_or(cat);
                let id = push_node(
                    &mut nodes,
                    &mut seq,
                    tier,
                    make_node(
                        format!("Cross-Reference {} — {} ⚔️ {}", tier + 1, game_name, g2),
                        format!("One grounded answer in each realm touching {} / {}.", cat, cat2),
                        NodeCriteria {
                            grounded_questions: 0,
                            category: None,
                            teach_facts: 0,
                            ordeal_run: 0,
                            comparative_realms: vec![game_name.clone(), g2.clone()],
                        },
                        "Each realm answers in its own time; the node holds partial progress per realm.".into(),
                        spec.curve.xp_at(tier) + 30,
                        rank_gate,
                        vec![
                            format!("{} — {} grimoire", cat, game_name),
                            format!("{} — {} grimoire", cat2, g2),
                        ],
                        prev.clone().into_iter().collect(),
                        false,
                        false,
                    ),
                );
                prev = Some(id);
            }
        }
        TreeArchetype::RestorationCampaign => {
            let mut prev: Option<String> = None;
            for tier in 0..spec.depth {
                let teach = 1 + tier / 2;
                let id = push_node(
                    &mut nodes,
                    &mut seq,
                    tier,
                    make_node(
                        format!("Restoration {} — re-ink the gaps", tier + 1),
                        format!("Teach {} fact(s) the {} grimoire is missing.", teach, game_name),
                        NodeCriteria {
                            grounded_questions: 0,
                            category: None,
                            teach_facts: teach,
                            ordeal_run: 0,
                            comparative_realms: vec![],
                        },
                        "Half-restored pages remain; each teaching endures even if the campaign rests.".into(),
                        spec.curve.xp_at(tier) + 20 * teach,
                        rank_gate,
                        vec![format!("{} grimoire (gaps)", game_name)],
                        prev.clone().into_iter().collect(),
                        false,
                        false,
                    ),
                );
                prev = Some(id);
            }
        }
        TreeArchetype::EdgeCaseGauntlet => {
            let mut prev: Option<String> = None;
            for tier in 0..spec.depth {
                let cat = cats_asc[tier as usize % cats_asc.len()];
                let id = push_node(
                    &mut nodes,
                    &mut seq,
                    tier,
                    make_node(
                        format!(
                            "Gauntlet Station {} — the uncharted {}",
                            tier + 1,
                            trim_cat(cat)
                        ),
                        format!("One grounded answer touching {} — the road less consulted.", cat),
                        NodeCriteria {
                            grounded_questions: 1,
                            category: Some(cat.to_string()),
                            teach_facts: 0,
                            ordeal_run: 0,
                            comparative_realms: vec![],
                        },
                        "Stations stand ready; a wrong road simply leaves the station unmarked.".into(),
                        spec.curve.xp_at(tier) + 25,
                        rank_gate,
                        vec![cat.to_string()],
                        prev.clone().into_iter().collect(),
                        false,
                        false,
                    ),
                );
                prev = Some(id);
            }
        }
    }

    let name = spec
        .name
        .clone()
        .unwrap_or_else(|| format!("{} — {}", game_name, spec.archetype.label()));
    Ok(QuestTree {
        id: tree_id,
        subtitle: spec.flavor.clone(),
        name,
        game: game_name,
        game2: game2_name,
        archetype: spec.archetype,
        curve: spec.curve,
        rank_gate,
        nodes,
        xp_earned: 0,
        completed_sealed: false,
        notes: String::new(),
        revisions: vec![RevisionEntry {
            date: Local::now().format("%Y-%m-%d %H:%M").to_string(),
            directive: "commission".into(),
            summary: format!(
                "{} · depth {} · breadth {} · {:?} curve",
                spec.archetype.label(),
                spec.depth,
                spec.breadth,
                spec.curve
            ),
            nodes_changed: 0,
        }],
        active: true,
        archived: false,
        created: Local::now().format("%Y-%m-%d").to_string(),
    })
}

// ---------------------------------------------------------------------------
// Event engine — real scholarship drives the trees
// ---------------------------------------------------------------------------

/// Outcome of routing one scholarship event through the atelier.
#[derive(Debug, Default)]
pub struct TreeOutcome {
    /// XP from nodes sealed by this event (add through add_experience).
    pub xp: u32,
    /// Narrative lines (node seals, tree seals).
    pub lines: Vec<String>,
}

/// Route one answer event through every living tree.
pub fn record_answer(
    trees: &mut [QuestTree],
    game: &GameType,
    tag: Option<&str>,
    grounded: bool,
) -> TreeOutcome {
    let mut out = TreeOutcome::default();
    let realm = game.get_name().to_string();
    for tree in trees.iter_mut() {
        if tree.archived || tree.completed_sealed {
            continue;
        }
        let involves = tree.game == realm
            || tree.game2.as_deref() == Some(realm.as_str())
            || tree
                .nodes
                .iter()
                .any(|n| n.criteria.comparative_realms.iter().any(|r| r == &realm));
        if !involves {
            continue;
        }
        if !grounded {
            // Faltering: reset live ordeal runs in this tree.
            for n in tree.nodes.iter_mut().filter(|n| !n.completed) {
                if n.criteria.ordeal_run > 0 {
                    n.progress = 0;
                }
            }
            continue;
        }
        let frontier = tree.frontier();
        let mut sealed_nodes: Vec<(String, u32)> = Vec::new();
        for nid in &frontier {
            let Some(node) = tree.nodes.iter_mut().find(|n| &n.id == nid) else {
                continue;
            };
            let cat_ok = node
                .criteria
                .category
                .as_deref()
                .map(|c| tag == Some(c))
                .unwrap_or(true);
            if node.criteria.grounded_questions > 0
                && cat_ok
                && node.progress < node.criteria.grounded_questions
            {
                node.progress += 1;
            }
            if node.criteria.ordeal_run > 0 {
                node.progress += 1;
            }
            if let Some(r) = node
                .criteria
                .comparative_realms
                .iter()
                .find(|r| **r == realm)
            {
                let e = node.realm_progress.entry(r.clone()).or_insert(0);
                if *e < 1 {
                    *e += 1;
                }
            }
            if node_complete(node) {
                node.completed = true;
                sealed_nodes.push((node.title.clone(), node.xp_reward));
            }
        }
        for (title, xp) in sealed_nodes {
            tree.xp_earned += xp;
            out.xp += xp;
            out.lines
                .push(format!("🌳 {} — node sealed: {} (+{} pages)", tree.name, title, xp));
        }
        // Rival paths of newly sealed nodes rest (skipped, not failed).
        let just_sealed: Vec<String> = tree
            .nodes
            .iter()
            .filter(|n| n.completed)
            .map(|n| n.id.clone())
            .collect();
        for n in tree.nodes.iter_mut() {
            if !n.completed
                && n.mutually_exclusive_with.iter().any(|x| just_sealed.contains(x))
            {
                n.completed = true;
                out.lines.push(format!(
                    "🌳 {} — the rival path '{}' rests (the chosen path prevails).",
                    tree.name, n.title
                ));
            }
        }
        // Tree seal: every non-optional node complete.
        let required_done = tree.nodes.iter().all(|n| n.completed || n.optional);
        if required_done && !tree.nodes.is_empty() && !tree.completed_sealed {
            tree.completed_sealed = true;
            let bonus = tree.xp_earned / 10;
            tree.xp_earned += bonus;
            out.xp += bonus;
            out.lines.push(format!(
                "🏆 Quest Tree sealed: **{}** — every required node complete. Order bonus: +{} pages.",
                tree.name, bonus
            ));
        }
    }
    out
}

/// Route one teaching event through the atelier (Restoration nodes).
pub fn record_teach(trees: &mut [QuestTree], game: &GameType) -> TreeOutcome {
    let mut out = TreeOutcome::default();
    let realm = game.get_name().to_string();
    for tree in trees.iter_mut() {
        if tree.archived || tree.completed_sealed || tree.game != realm {
            continue;
        }
        let frontier = tree.frontier();
        let mut sealed: Vec<(String, u32)> = Vec::new();
        for nid in &frontier {
            let Some(node) = tree.nodes.iter_mut().find(|n| &n.id == nid) else {
                continue;
            };
            if node.criteria.teach_facts > 0 && node.teach_progress < node.criteria.teach_facts {
                node.teach_progress += 1;
            }
            if node_complete(node) {
                node.completed = true;
                sealed.push((node.title.clone(), node.xp_reward));
            }
        }
        for (title, xp) in sealed {
            tree.xp_earned += xp;
            out.xp += xp;
            out.lines
                .push(format!("🌳 {} — node sealed: {} (+{} pages)", tree.name, title, xp));
        }
    }
    out
}

fn node_complete(node: &TreeNode) -> bool {
    let counters_done = (node.criteria.grounded_questions == 0
        || node.progress >= node.criteria.grounded_questions)
        && (node.criteria.teach_facts == 0 || node.teach_progress >= node.criteria.teach_facts)
        && (node.criteria.ordeal_run == 0 || node.progress >= node.criteria.ordeal_run);
    let comparative_done = node
        .criteria
        .comparative_realms
        .iter()
        .all(|r| node.realm_progress.get(r).copied().unwrap_or(0) >= 1);
    counters_done && comparative_done && node.target() > 0
}

// ---------------------------------------------------------------------------
// Integrity: validation & repair against the current grimoire
// ---------------------------------------------------------------------------

/// Re-check every node's sections against the current grimoire. Returns the
/// number of stale nodes found per tree id (empty map = nothing stale).
pub fn validate_trees(trees: &mut [QuestTree], kb: &KnowledgeBase) -> BTreeMap<String, usize> {
    let mut report = BTreeMap::new();
    for tree in trees.iter_mut() {
        let Some(game) = crate::codex::Codex::match_game(&tree.game) else {
            continue;
        };
        let cats: Vec<&'static str> = {
            let mut m: BTreeMap<&'static str, ()> = BTreeMap::new();
            for e in kb.entries_for_game(&game) {
                m.entry(e.category.label()).or_insert(());
            }
            m.into_keys().collect()
        };
        let mut stale = 0;
        for n in tree.nodes.iter_mut() {
            let missing = n.grimoire_sections.iter().any(|s| {
                !s.contains("(gaps)")
                    && !s.contains("consecutive grounded")
                    && !cats.iter().any(|c| s.contains(c))
            });
            n.stale = missing;
            if missing {
                stale += 1;
            }
        }
        if stale > 0 {
            report.insert(tree.id.clone(), stale);
        }
    }
    report
}

/// Repair a tree: re-bind stale nodes to disciplines that still exist.
pub fn repair_tree(tree: &mut QuestTree, kb: &KnowledgeBase) -> u32 {
    let Some(game) = crate::codex::Codex::match_game(&tree.game) else {
        return 0;
    };
    let cats: Vec<&'static str> = {
        let mut m: BTreeMap<&'static str, ()> = BTreeMap::new();
        for e in kb.entries_for_game(&game) {
            m.entry(e.category.label()).or_insert(());
        }
        m.into_keys().collect()
    };
    let mut repaired = 0;
    for n in tree.nodes.iter_mut().filter(|n| n.stale) {
        if let Some(cat) = cats.first() {
            n.grimoire_sections = vec![cat.to_string()];
            if n.criteria.category.is_some() {
                n.criteria.category = Some(cat.to_string());
            }
            n.stale = false;
            repaired += 1;
        }
    }
    if repaired > 0 {
        tree.revisions.push(RevisionEntry {
            date: Local::now().format("%Y-%m-%d %H:%M").to_string(),
            directive: "repair".into(),
            summary: format!("{} stale node(s) re-bound to living sections", repaired),
            nodes_changed: repaired,
        });
    }
    repaired
}

