// Visual graph — layout, and manual completion mechanics
// ---------------------------------------------------------------------------

/// A positioned node for the interactive graph surface.
#[derive(Debug, Clone)]
pub struct GNode {
    pub id: String,
    pub tier: u32,
    /// Row index within its tier (for vertical placement).
    pub row: u32,
    /// 0 = locked, 1 = available (frontier), 2 = completed.
    pub state: u8,
    pub title: String,
    pub optional: bool,
    pub stale: bool,
}

/// Automatic hierarchy layout: tiers as columns, nodes centered per column.
/// Returns nodes in stable (tier, row) order with normalized 0..1 coordinates.
pub fn layout(tree: &QuestTree) -> Vec<GNode> {
    // Group by tier, preserving node order.
    let mut tiers: BTreeMap<u32, Vec<&TreeNode>> = BTreeMap::new();
    for n in &tree.nodes {
        tiers.entry(n.tier).or_default().push(n);
    }
    let max_tier = tiers.keys().copied().max().unwrap_or(0);
    let mut out = Vec::new();
    for (&tier, nodes) in &tiers {
        let count = nodes.len() as u32;
        for (row, n) in nodes.iter().enumerate() {
            let completed = n.completed;
            let frontier = tree.frontier().contains(&n.id);
            out.push(GNode {
                id: n.id.clone(),
                tier,
                row: row as u32,
                state: if completed {
                    2
                } else if frontier {
                    1
                } else {
                    0
                },
                title: n.title.clone(),
                optional: n.optional,
                stale: n.stale,
            });
            let _ = count;
        }
    }
    let _ = max_tier;
    out
}

/// Edges as (from_index, to_index) into the layout vector.
pub fn layout_edges(tree: &QuestTree, nodes: &[GNode]) -> Vec<(usize, usize)> {
    let idx = |id: &str| nodes.iter().position(|n| n.id == id);
    let mut edges = Vec::new();
    for (ti, n) in tree.nodes.iter().enumerate() {
        for p in &n.parents {
            if let (Some(from), Some(to)) = (idx(p), idx(&n.id)) {
                let _ = ti;
                edges.push((from, to));
            }
        }
    }
    edges
}

/// Manually seal one node ("Mark Done"). Only frontier nodes may be sealed:
/// a locked node returns a gentle, in-character refusal. On success the node
/// is sealed, its XP returned (caller adds it through the global economy),
/// the tree seal bonus checked, and the newly lit successor ids returned so
/// the graph can animate the forward path.
pub fn complete_node(
    tree: &mut QuestTree,
    node_id: &str,
) -> Result<(u32, Vec<String>, Vec<String>), String> {
    if tree.completed_sealed {
        return Err("This tree is already sealed — every required node complete.".into());
    }
    let frontier = tree.frontier();
    let Some(pos) = tree.nodes.iter().position(|n| n.id == node_id) else {
        return Err("That node is not inscribed in this tree.".into());
    };
    if !frontier.iter().any(|id| id == node_id) {
        // Gentle, in-character refusal with the reason.
        let node = &tree.nodes[pos];
        let missing: Vec<String> = node
            .parents
            .iter()
            .filter(|p| {
                tree.nodes
                    .iter()
                    .find(|c| c.id == **p)
                    .map(|c| !c.completed && !c.optional)
                    .unwrap_or(false)
            })
            .filter_map(|p| {
                tree.nodes
                    .iter()
                    .find(|c| &c.id == p)
                    .map(|c| c.title.clone())
            })
            .collect();
        return Err(if missing.is_empty() {
            format!(
                "🕯️ '{}' is not yet within reach — its moment has not come. Walk the lit paths first.",
                node.title
            )
        } else {
            format!(
                "🕯️ '{}' is sealed behind its prerequisites: {}. Complete those chapters first — the path will light itself.",
                node.title,
                missing.join(", ")
            )
        });
    }
    tree.nodes[pos].completed = true;
    let xp = tree.nodes[pos].xp_reward;
    let title = tree.nodes[pos].title.clone();
    tree.xp_earned += xp;
    // Rivals rest.
    let rivals: Vec<String> = tree.nodes[pos].mutually_exclusive_with.clone();
    for n in tree.nodes.iter_mut() {
        if !n.completed && rivals.contains(&n.id) {
            n.completed = true;
        }
    }
    // Newly lit successors: children of the sealed node now in the frontier.
    let lit: Vec<String> = tree
        .nodes
        .iter()
        .filter(|n| n.parents.contains(&node_id.to_string()) && tree.frontier().contains(&n.id))
        .map(|n| n.id.clone())
        .collect();
    let mut lines = vec![format!(
        "🌳 Node sealed: {} (+{} pages) — the forward path lights the way.",
        title, xp
    )];
    // Tree seal.
    let required_done = tree.nodes.iter().all(|n| n.completed || n.optional);
    if required_done && !tree.completed_sealed {
        tree.completed_sealed = true;
        let bonus = tree.xp_earned / 10;
        tree.xp_earned += bonus;
        lines.push(format!(
            "🏆 Quest Tree sealed: **{}** — Order bonus: +{} pages.",
            tree.name, bonus
        ));
        return Ok((xp + bonus, lines, lit));
    }
    tree.revisions.push(RevisionEntry {
        date: Local::now().format("%Y-%m-%d %H:%M").to_string(),
        directive: "node_sealed".into(),
        summary: format!("'{}' marked done by hand", title),
        nodes_changed: 1,
    });
    Ok((xp, lines, lit))
}

/// Pure textual outline of the whole tree (indented hierarchy).
pub fn outline(tree: &QuestTree) -> String {
    let mut out = format!(
        "🌳 **{}** — {} · {} · {} pages earned\n",
        tree.name,
        tree.archetype.label(),
        if tree.completed_sealed { "SEALED" } else { "in progress" },
        tree.xp_earned
    );
    if let Some(f) = &tree.subtitle {
        out.push_str(&format!("   *“{}”*\n", f));
    }
    let frontier = tree.frontier();
    for n in &tree.nodes {
        let mark = if n.completed {
            "✅"
        } else if frontier.contains(&n.id) {
            "⚔️"
        } else if n.stale {
            "⚠️"
        } else {
            "🔒"
        };
        out.push_str(&format!(
            "- {} [T{}] {} — {} · +{} pages · 📚 {}\n",
            mark,
            n.tier,
            n.title,
            n.progress_line(),
            n.xp_reward,
            n.grimoire_sections.join(", ")
        ));
    }
    out
}

/// An in-progress conversational commission (the Create Tree guided flow).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CommissionDraft {
    /// 0 = awaiting the game, 1 = awaiting the shape.
    pub step: usize,
    #[serde(default)]
    pub suggested_game: Option<String>,
    #[serde(default)]
    pub game: Option<String>,
}

impl Default for CommissionDraft {
    fn default() -> Self {
        Self { step: 0, suggested_game: None, game: None }
    }
}
